#pragma once

#ifndef TAGOBJECT_H
#define TAGOBJECT_H

#include "TagimgSchema.h"

namespace graphql::tagimg::object {
namespace methods::TagHas {

template <class TImpl>
concept getIdWithParams = requires (TImpl impl, service::FieldParams params)
{
	{ service::AwaitableScalar<response::IdType> { impl.getId(std::move(params)) } };
};

template <class TImpl>
concept getId = requires (TImpl impl)
{
	{ service::AwaitableScalar<response::IdType> { impl.getId() } };
};

template <class TImpl>
concept getNameWithParams = requires (TImpl impl, service::FieldParams params)
{
	{ service::AwaitableScalar<std::string> { impl.getName(std::move(params)) } };
};

template <class TImpl>
concept getName = requires (TImpl impl)
{
	{ service::AwaitableScalar<std::string> { impl.getName() } };
};

template <class TImpl>
concept getCategoryWithParams = requires (TImpl impl, service::FieldParams params)
{
	{ service::AwaitableScalar<std::optional<std::string>> { impl.getCategory(std::move(params)) } };
};

template <class TImpl>
concept getCategory = requires (TImpl impl)
{
	{ service::AwaitableScalar<std::optional<std::string>> { impl.getCategory() } };
};

template <class TImpl>
concept getAliasesWithParams = requires (TImpl impl, service::FieldParams params)
{
	{ service::AwaitableScalar<std::vector<std::string>> { impl.getAliases(std::move(params)) } };
};

template <class TImpl>
concept getAliases = requires (TImpl impl)
{
	{ service::AwaitableScalar<std::vector<std::string>> { impl.getAliases() } };
};

template <class TImpl>
concept beginSelectionSet = requires (TImpl impl, const service::SelectionSetParams params)
{
	{ impl.beginSelectionSet(params) };
};

template <class TImpl>
concept endSelectionSet = requires (TImpl impl, const service::SelectionSetParams params)
{
	{ impl.endSelectionSet(params) };
};

} // namespace methods::TagHas

class [[nodiscard("unnecessary construction")]] Tag final
	: public service::Object
{
private:
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveId(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveName(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveCategory(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveAliases(service::ResolverParams&& params) const;

	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_typename(service::ResolverParams&& params) const;

	struct [[nodiscard("unnecessary construction")]] Concept
	{
		virtual ~Concept() = default;

		virtual void beginSelectionSet(const service::SelectionSetParams& params) const = 0;
		virtual void endSelectionSet(const service::SelectionSetParams& params) const = 0;

		[[nodiscard("unnecessary call")]] virtual service::AwaitableScalar<response::IdType> getId(service::FieldParams&& params) const = 0;
		[[nodiscard("unnecessary call")]] virtual service::AwaitableScalar<std::string> getName(service::FieldParams&& params) const = 0;
		[[nodiscard("unnecessary call")]] virtual service::AwaitableScalar<std::optional<std::string>> getCategory(service::FieldParams&& params) const = 0;
		[[nodiscard("unnecessary call")]] virtual service::AwaitableScalar<std::vector<std::string>> getAliases(service::FieldParams&& params) const = 0;
	};

	template <class T>
	struct [[nodiscard("unnecessary construction")]] Model final
		: Concept
	{
		explicit Model(std::shared_ptr<T> pimpl) noexcept
			: _pimpl { std::move(pimpl) }
		{
		}

		[[nodiscard("unnecessary call")]] service::AwaitableScalar<response::IdType> getId(service::FieldParams&& params) const override
		{
			if constexpr (methods::TagHas::getIdWithParams<T>)
			{
				return { _pimpl->getId(std::move(params)) };
			}
			else
			{
				static_assert(methods::TagHas::getId<T>, R"msg(Tag::getId is not implemented)msg");
				return { _pimpl->getId() };
			}
		}

		[[nodiscard("unnecessary call")]] service::AwaitableScalar<std::string> getName(service::FieldParams&& params) const override
		{
			if constexpr (methods::TagHas::getNameWithParams<T>)
			{
				return { _pimpl->getName(std::move(params)) };
			}
			else
			{
				static_assert(methods::TagHas::getName<T>, R"msg(Tag::getName is not implemented)msg");
				return { _pimpl->getName() };
			}
		}

		[[nodiscard("unnecessary call")]] service::AwaitableScalar<std::optional<std::string>> getCategory(service::FieldParams&& params) const override
		{
			if constexpr (methods::TagHas::getCategoryWithParams<T>)
			{
				return { _pimpl->getCategory(std::move(params)) };
			}
			else
			{
				static_assert(methods::TagHas::getCategory<T>, R"msg(Tag::getCategory is not implemented)msg");
				return { _pimpl->getCategory() };
			}
		}

		[[nodiscard("unnecessary call")]] service::AwaitableScalar<std::vector<std::string>> getAliases(service::FieldParams&& params) const override
		{
			if constexpr (methods::TagHas::getAliasesWithParams<T>)
			{
				return { _pimpl->getAliases(std::move(params)) };
			}
			else
			{
				static_assert(methods::TagHas::getAliases<T>, R"msg(Tag::getAliases is not implemented)msg");
				return { _pimpl->getAliases() };
			}
		}

		void beginSelectionSet(const service::SelectionSetParams& params) const override
		{
			if constexpr (methods::TagHas::beginSelectionSet<T>)
			{
				_pimpl->beginSelectionSet(params);
			}
		}

		void endSelectionSet(const service::SelectionSetParams& params) const override
		{
			if constexpr (methods::TagHas::endSelectionSet<T>)
			{
				_pimpl->endSelectionSet(params);
			}
		}

	private:
		const std::shared_ptr<T> _pimpl;
	};

	explicit Tag(std::unique_ptr<const Concept> pimpl) noexcept;

	[[nodiscard("unnecessary call")]] service::TypeNames getTypeNames() const noexcept;
	[[nodiscard("unnecessary call")]] service::ResolverMap getResolvers() const noexcept;

	void beginSelectionSet(const service::SelectionSetParams& params) const override;
	void endSelectionSet(const service::SelectionSetParams& params) const override;

	const std::unique_ptr<const Concept> _pimpl;

public:
	template <class T>
	explicit Tag(std::shared_ptr<T> pimpl) noexcept
		: Tag { std::unique_ptr<const Concept> { std::make_unique<Model<T>>(std::move(pimpl)) } }
	{
	}

	[[nodiscard("unnecessary call")]] static constexpr std::string_view getObjectType() noexcept
	{
		return { R"gql(Tag)gql" };
	}
};

} // namespace graphql::tagimg::object

#endif // TAGOBJECT_H
